import android.hardware.camera2.*;
import com.android.camera.one.*;import com.android.camera.one.OneCamera.Facing;
import com.android.camera.one.v2.*;import com.android.camera.device.CameraId;
public class HotplugRegression {
 interface Check{void run()throws Exception;}
 static int passed=0;
 static void check(boolean ok){if(!ok)throw new AssertionError();}
 static void run(String name,Check c)throws Exception{c.run();passed++;System.out.println("PASS "+name);}
 static CameraCharacteristics add(CameraManager m,String id,Integer facing){CameraCharacteristics c=new CameraCharacteristics(facing);m.devices.put(id,c);return c;}
 static Camera2OneCameraManagerImpl manager(CameraManager m){return new Camera2OneCameraManagerImpl(m);}
 public static void main(String[] args)throws Exception{
  run("healthy characteristics and selected facing",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);CameraCharacteristics c=add(m,"ok",1);m.ids=new String[]{"ok"};check(a.hasCamera());check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("ok"));check(a.getCameraCharacteristics(CameraId.from("ok"))==c);check(((OneCameraCharacteristicsImpl)a.getOneCameraCharacteristics(CameraId.from("ok"))).raw==c);});
  run("enumerated device disappears before characteristics",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"gone",1);m.ids=new String[]{"gone"};CameraId id=a.findFirstCameraFacing(Facing.BACK);m.ids=new String[0];m.devices.clear();try{a.getCameraCharacteristics(id);throw new AssertionError();}catch(OneCameraAccessException e){check(e.getCause() instanceof IllegalArgumentException);}check(a.findFirstCameraFacing(Facing.BACK)==null);});
  run("enumeration race preserves remaining connected device",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"ok",1);m.ids=new String[]{"gone","ok"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("ok"));});
  run("cached device removal selects replacement",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"old",1);m.ids=new String[]{"old"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("old"));m.devices.clear();add(m,"new",1);m.ids=new String[]{"new"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("new"));});
  run("camera service checked failure retains cause",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);CameraAccessException failure=new CameraAccessException("service unavailable");m.queryFailure=failure;try{a.getCameraCharacteristics(CameraId.from("x"));throw new AssertionError();}catch(OneCameraAccessException e){check(e.getCause()==failure);}});
  run("unrelated runtime failure is not swallowed",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);RuntimeException failure=new IllegalStateException("programming error");m.queryRuntime=failure;try{a.getCameraCharacteristics(CameraId.from("x"));throw new AssertionError();}catch(IllegalStateException e){check(e==failure);}});
  run("missing lens facing skipped",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"missing",null);add(m,"ok",1);m.ids=new String[]{"missing","ok"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("ok"));});
  run("null device list is unavailable",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);m.ids=null;check(!a.hasCamera());check(a.findFirstCamera()==null);check(a.findFirstCameraFacing(Facing.BACK)==null);});
  run("null ID entry skipped",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"ok",1);m.ids=new String[]{null,"ok"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("ok"));});
  run("null selected device becomes checked failure",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);try{a.getCameraCharacteristics(null);throw new AssertionError();}catch(OneCameraAccessException expected){}try{a.getCameraCharacteristics(CameraId.from(null));throw new AssertionError();}catch(OneCameraAccessException expected){}});
  run("null characteristics becomes checked failure",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);m.returnNull=true;try{a.getCameraCharacteristics(CameraId.from("x"));throw new AssertionError();}catch(OneCameraAccessException expected){}m.ids=new String[]{"x"};check(a.findFirstCameraFacing(Facing.BACK)==null);});
  run("availability event invalidates same ID facing cache",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"same",1);m.ids=new String[]{"same"};check(a.findFirstCameraFacing(Facing.BACK)!=null);m.devices.get("same").facing=0;a.onCameraUnavailable("same");check(a.findFirstCameraFacing(Facing.BACK)==null);check(a.findFirstCameraFacing(Facing.FRONT)!=null);m.devices.get("same").facing=1;a.onCameraAvailable("same");check(a.findFirstCameraFacing(Facing.FRONT)==null);});
  run("cached ID list failure reports unavailable",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"old",1);m.ids=new String[]{"old"};check(a.findFirstCameraFacing(Facing.BACK)!=null);m.listFailure=new CameraAccessException("service unavailable");check(a.findFirstCameraFacing(Facing.BACK)==null);});
  run("external camera fallback retained",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);add(m,"usb",2);m.ids=new String[]{"usb"};check(a.findFirstCameraFacing(Facing.BACK).getValue().equals("usb"));check(a.findFirstCameraFacing(Facing.FRONT).getValue().equals("usb"));});
  run("callback registration and teardown retained",()->{CameraManager m=new CameraManager();Camera2OneCameraManagerImpl a=manager(m);final int[] calls={0};a.setAvailabilityCallback(()->calls[0]++,new android.os.Handler());a.onCameraAccessPrioritiesChanged();check(calls[0]==1&&m.registered==1);a.setAvailabilityCallback(null,null);a.onCameraAccessPrioritiesChanged();check(calls[0]==1&&m.unregistered==1);});
  System.out.println("TOTAL_PASS="+passed);
 }
}
